1	package release
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	const (
10		opCreateBatch = "createBatch"
11		opUpdateDraft = "updateDraftBatch"
12		opStartBatch  = "startBatch"
13		opCloseBatch  = "closeBatch"
14		opAddFeeding  = "addFeeding"
15	)
16	
17	type createBatchPayload struct {
18		BatchNo  string
19		RecipeNo string
20		Version  string
21		Portions int
22	}
23	
24	type updateDraftPayload struct {
25		BatchNo  string
26		RecipeNo string // 留空表示不改配方
27		Version  string // 与 RecipeNo 同时给出
28		Portions int    // 0 表示不改份数
29	}
30	
31	type startBatchPayload struct {
32		BatchNo string
33	}
34	
35	type closeBatchPayload struct {
36		BatchNo string
37	}
38	
39	type addFeedingPayload struct {
40		BatchNo    string
41		MaterialNo string
42		Grams      string
43		Time       time.Time
44		Registrar  string
45	}
46	
47	// CreateBatch 创建批次。
48	// 批次使用独立批次编号，选择已登记的配方版本和计划份数（必须为正整数）。
49	// 新批次为草稿；批次编号重复、配方版本不存在或数量不合法时返回具体原因且不保留数据。
50	func (s *Store) CreateBatch(reqNo, batchNo, recipeNo, version string, portions int) (*BatchView, error) {
51		payload := createBatchPayload{BatchNo: batchNo, RecipeNo: recipeNo, Version: version, Portions: portions}
52		var out BatchView
53		err := s.write(reqNo, opCreateBatch, payload, func(st *persistedState) (json.RawMessage, error) {
54			if batchNo == "" {
55				return nil, fmt.Errorf("%w: 批次编号不能为空", ErrInvalidInput)
56			}
57			if portions <= 0 {
58				return nil, fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidInput, portions)
59			}
60			if findBatch(st, batchNo) != nil {
61				return nil, fmt.Errorf("%w: 批次 %q 已存在", ErrDuplicateBatch, batchNo)
62			}
63			r := findRecipe(st, recipeNo, version)
64			if r == nil {
65				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 不存在", ErrNotFound, recipeNo, version)
66			}
67			// 份数为正整数还要满足：按该配方版本逐物料计算的应投量都能精确
68			// 表示且不超上限。这是本次提交的输入规则，不满足按 ErrInvalidInput
69			// 拒绝，不能落盘成之后读取时才发现损坏的批次。
70			if err := validatePlanForRecipe(r, portions); err != nil {
71				return nil, fmt.Errorf("%w: %v", ErrInvalidInput, err)
72			}
73			b := &batchRecord{
74				BatchNo:         batchNo,
75				RecipeNo:        recipeNo,
76				RecipeVersion:   version,
77				PlannedPortions: portions,
78				Status:          StatusDraft,
79			}
80			view, err := buildBatchView(b, r)
81			if err != nil {
82				return nil, err
83			}
84			raw, err := json.Marshal(view)
85			if err != nil {
86				return nil, err
87			}
88			st.Batches = append(st.Batches, b)
89			return raw, nil
90		}, &out)
91		if err != nil {
92			return nil, err
93		}
94		return &out, nil
95	}
96	
97	// UpdateDraftBatch 调整草稿批次的计划份数或改选配方版本。
98	// newRecipeNo/newVersion 都留空表示不改配方；newPortions 传 0 表示不改份数。
99	// 只有草稿状态可以调整；开始执行后两者固定。
100	func (s *Store) UpdateDraftBatch(reqNo, batchNo, newRecipeNo, newVersion string, newPortions int) (*BatchView, error) {
101		payload := updateDraftPayload{BatchNo: batchNo, RecipeNo: newRecipeNo, Version: newVersion, Portions: newPortions}
102		var out BatchView
103		err := s.write(reqNo, opUpdateDraft, payload, func(st *persistedState) (json.RawMessage, error) {
104			b := findBatch(st, batchNo)
105			if b == nil {
106				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
107			}
108			if b.Status != StatusDraft {
109				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有草稿可以调整", ErrInvalidState, batchNo, b.Status)
110			}
111			// 先解析调整后的最终份数与配方版本（份数传 0 表示沿用原份数，
112			// 配方编号与版本号都留空表示沿用原版本），全部解析并校验通过
113			// 后才改动记录，保证失败时不留下半调整状态。
114			finalPortions := b.PlannedPortions
115			if newPortions != 0 {
116				if newPortions <= 0 {
117					return nil, fmt.Errorf("%w: 计划份数必须为正整数，得到 %d", ErrInvalidInput, newPortions)
118				}
119				finalPortions = newPortions
120			}
121			finalRecipeNo, finalVersion := b.RecipeNo, b.RecipeVersion
122			if newRecipeNo != "" || newVersion != "" {
123				if newRecipeNo == "" || newVersion == "" {
124					return nil, fmt.Errorf("%w: 改选配方版本时必须同时给出配方编号和版本号", ErrInvalidInput)
125				}
126				finalRecipeNo, finalVersion = newRecipeNo, newVersion
127			}
128			r := findRecipe(st, finalRecipeNo, finalVersion)
129			if r == nil {
130				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 不存在", ErrNotFound, finalRecipeNo, finalVersion)
131			}
132			// 最终计划同样必须满足：每种物料按最终版本、最终份数计算的应投量
133			// 都能精确表示且不超上限；沿用合法原计划（无变化调整）时该校验
134			// 在读取时已经通过，这里再统一校验一次。这是本次提交的输入规则，
135			// 不满足按 ErrInvalidInput 整体拒绝，不落盘份数或配方的半成品。
136			if err := validatePlanForRecipe(r, finalPortions); err != nil {
137				return nil, fmt.Errorf("%w: %v", ErrInvalidInput, err)
138			}
139			b.PlannedPortions = finalPortions
140			b.RecipeNo = finalRecipeNo
141			b.RecipeVersion = finalVersion
142			view, err := buildBatchView(b, r)
143			if err != nil {
144				return nil, err
145			}
146			raw, err := json.Marshal(view)
147			if err != nil {
148				return nil, err
149			}
150			return raw, nil
151		}, &out)
152		if err != nil {
153			return nil, err
154		}
155		return &out, nil
156	}
157	
158	// StartBatch 开始执行批次：草稿 → 执行中。
159	// 开始后计划份数与配方版本固定，只有执行中的批次可以关闭。
160	func (s *Store) StartBatch(reqNo, batchNo string) (*BatchView, error) {
161		payload := startBatchPayload{BatchNo: batchNo}
162		var out BatchView
163		err := s.write(reqNo, opStartBatch, payload, func(st *persistedState) (json.RawMessage, error) {
164			return transitionBatchStatus(st, batchNo, StatusDraft, StatusExecuting, "只有草稿可以开始执行")
165		}, &out)
166		if err != nil {
167			return nil, err
168		}
169		return &out, nil
170	}
171	
172	// CloseBatch 关闭批次：执行中 → 已关闭。
173	// 关闭表示确认已有投料，不要求数量已经吻合；
174	// 关闭后不能追加投料，也不能重新打开。
175	func (s *Store) CloseBatch(reqNo, batchNo string) (*BatchView, error) {
176		payload := closeBatchPayload{BatchNo: batchNo}
177		var out BatchView
178		err := s.write(reqNo, opCloseBatch, payload, func(st *persistedState) (json.RawMessage, error) {
179			return transitionBatchStatus(st, batchNo, StatusExecuting, StatusClosed, "只有执行中的批次可以关闭")
180		}, &out)
181		if err != nil {
182			return nil, err
183		}
184		return &out, nil
185	}
186	
187	// transitionBatchStatus 是批次状态变更（开始执行、关闭）的统一实现：
188	// 找到批次后要求当前状态为 from，否则按 ErrInvalidState 拒绝（批次不存在
189	// 按 ErrNotFound 拒绝，两种情况下状态与投料都不变）；通过后将状态改为 to，
190	// 并按变更后的记录构造返回视图。rule 说明该变更的准入规则，用于状态不符时
191	// 的错误信息。配方版本、计划份数与已有投料均保持原样。
192	func transitionBatchStatus(st *persistedState, batchNo string, from, to BatchStatus, rule string) (json.RawMessage, error) {
193		b := findBatch(st, batchNo)
194		if b == nil {
195			return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
196		}
197		if b.Status != from {
198			return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，%s", ErrInvalidState, batchNo, b.Status, rule)
199		}
200		b.Status = to
201		r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
202		if r == nil {
203			return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
204				ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
205		}
206		view, err := buildBatchView(b, r)
207		if err != nil {
208			return nil, err
209		}
210		raw, err := json.Marshal(view)
211		if err != nil {
212			return nil, err
213		}
214		return raw, nil
215	}
216	
217	// AddFeeding 向执行中的批次追加一次投料。
218	// 投料包含物料编号、克数（正数、最多三位小数）、投料时间和登记人；
219	// 物料必须属于该批次绑定的配方版本。允许实际投料不足或超过应投量；
220	// 已登记的投料不能修改或删除，关闭后也不能追加。
221	// 同一批次内每种物料的累计实投量（仅按该物料统计）上限为
222	// 9223372036854775.807 克，本次投料后恰好等于上限仍允许，超过则返回
223	// ErrInvalidInput 且不保存本次投料。
224	// 投料按成功登记的先后顺序编号，不按投料时间重排。
225	func (s *Store) AddFeeding(reqNo, batchNo, materialNo, grams string, t time.Time, registrar string) (*FeedingView, error) {
226		payload := addFeedingPayload{
227			BatchNo:    batchNo,
228			MaterialNo: materialNo,
229			Grams:      grams,
230			Time:       t,
231			Registrar:  registrar,
232		}
233		var out FeedingView
234		err := s.write(reqNo, opAddFeeding, payload, func(st *persistedState) (json.RawMessage, error) {
235			if materialNo == "" {
236				return nil, fmt.Errorf("%w: 物料编号不能为空", ErrInvalidInput)
237			}
238			if registrar == "" {
239				return nil, fmt.Errorf("%w: 登记人不能为空", ErrInvalidInput)
240			}
241			milli, err := parseGrams(grams)
242			if err != nil {
243				return nil, fmt.Errorf("%w: 物料 %q 的克数: %v", ErrInvalidInput, materialNo, err)
244			}
245			b := findBatch(st, batchNo)
246			if b == nil {
247				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
248			}
249			if b.Status != StatusExecuting {
250				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有执行中的批次可以投料", ErrInvalidState, batchNo, b.Status)
251			}
252			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
253			if r == nil {
254				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
255					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
256			}
257			belongs := false
258			for _, m := range r.Materials {
259				if m.MaterialNo == materialNo {
260					belongs = true
261					break
262				}
263			}
264			if !belongs {
265				return nil, fmt.Errorf("%w: 物料 %q 不在配方 %q 版本 %q 中",
266					ErrMaterialNotInRecipe, materialNo, r.RecipeNo, r.Version)
267			}
268	
269			// 上限按物料分别判断：只累计该物料已登记的投料，
270			// 其他物料的投料量不参与，也不互相抵消。
271			acc := newFeedingAccumulator()
272			fit := true
273			for _, f := range b.Feedings {
274				if !acc.add(f.MaterialNo, f.GramsMilli) {
275					fit = false
276					break
277				}
278			}
279			if !fit || !acc.add(materialNo, milli) {
280				return nil, fmt.Errorf("%w: 物料 %q 的数量超出范围：本次投料后累计实投将超过上限 %s 克",
281					ErrInvalidInput, materialNo, maxGramsMilli)
282			}
283	
284			seq := len(b.Feedings) + 1
285			rec := feedingRecord{
286				Seq:        seq,
287				MaterialNo: materialNo,
288				GramsMilli: milli,
289				Time:       t,
290				Registrar:  registrar,
291			}
292			view := FeedingView{
293				Seq:        seq,
294				MaterialNo: materialNo,
295				Grams:      milli.String(),
296				Time:       t,
297				Registrar:  registrar,
298			}
299			raw, err := json.Marshal(view)
300			if err != nil {
301				return nil, err
302			}
303			b.Feedings = append(b.Feedings, rec)
304			return raw, nil
305		}, &out)
306		if err != nil {
307			return nil, err
308		}
309		return &out, nil
310	}
311	
312	// GetBatch 按批次编号查询，返回未找到（ErrNotFound）时表示批次不存在。
313	// 返回内容包含所用配方版本、计划份数、状态、全部投料（登记顺序），
314	// 以及按物料逐项的应投量、累计实投量和差额；无投料的物料也会列出。
315	// 返回的视图是台账数据的副本，调用方修改不会影响台账。
316	func (s *Store) GetBatch(batchNo string) (*BatchView, error) {
317		var out *BatchView
318		err := s.read(func(st *persistedState) error {
319			b := findBatch(st, batchNo)
320			if b == nil {
321				return fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
322			}
323			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
324			if r == nil {
325				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 不存在",
326					ErrCorruptData, batchNo, b.RecipeNo, b.RecipeVersion)
327			}
328			view, err := buildBatchView(b, r)
329			if err != nil {
330				return err
331			}
332			out = view
333			return nil
334		})
335		if err != nil {
336			return nil, err
337		}
338		return out, nil
339	}
340

