894	
895		s2, err := Open(dir)
896		if err != nil {
897			t.Fatal(err)
898		}
899		defer s2.Close()
900		got, err := s2.GetBatch("B1")
901		if err != nil {
902			t.Fatal(err)
903		}
904		if len(got.Feedings) != 40 {
905			t.Fatalf("两个进程共应登记 40 条投料，得到 %d 条（数据被覆盖）", len(got.Feedings))
906		}
