116	// 不与同批次其他物料的应投量相加；恰好等于上限合法，再大即溢出。
117	// 计算不回绕、不截断、不舍入。
118	func multiplyPortions(g gramsMilli, portions int) (gramsMilli, error) {
119		if portions <= 0 {
