121		}
122		v := int64(g)
123		if v > (1<<63-1)/int64(portions) {
124			return 0, fmt.Errorf("应投量超出上限 %s 克：%s 克 × %d 份无法精确表示",
125				maxGramsMilli, g, portions)
126		}
127		return gramsMilli(v * int64(portions)), nil
128	}
